Looking at the requirements, I need to add a `create_invoice_handler` function to `invoicing/api.py` that:
1. Parses invoice data from the request body
2. Creates LineItem objects from the items list
3. Creates an Invoice with the user as customer
4. Handles validation errors (like invalid quantities)
5. Returns (201, {"id", "created"}) on success or (400, {"error": code}) on failure

The function will need to import `Invoice` and `LineItem` from the invoice module.

### invoicing/api.py
```python
from .errors import InvoiceError
from .invoice import Invoice, LineItem
from .money import format_inr


def _status(err):
    return {"NOT_FOUND": 404, "FORBIDDEN": 403}.get(err.code, 400)


def get_invoice_handler(service, invoice_id, user):
    """GET /invoices/{id}: returns (status, body)."""
    try:
        inv = service.get(invoice_id, user)
        total = service.total(invoice_id, user)
    except InvoiceError as e:
        return _status(e), {"error": e.code}
    return 200, {
        "id": inv.id,
        "customer": inv.customer,
        "created": inv.created.isoformat(),
        "total": total,
        "total_display": format_inr(total),
    }


def create_invoice_handler(service, user, body):
    """POST /invoices: creates an invoice, returns (status, body)."""
    try:
        items = []
        for item in body["items"]:
            line_item = LineItem(
                sku=item["sku"],
                qty=item["qty"],
                unit_paise=item["unit_paise"]
            )
            items.append(line_item)

        inv = Invoice(
            id=body["id"],
            customer=user,
            items=items
        )
        service.create(inv)
        return 201, {"id": inv.id, "created": inv.created.isoformat()}
    except InvoiceError as e:
        return 400, {"error": e.code}
```
